-- Task 8: the synthetic canary, and an alarm for a Stripe that has stopped answering.
-- One migration for all three changes, generated by drizzle-kit and then hand-guarded
-- so a reset Neon branch can replay it.
--
-- 1. `locations.synthetic` — a location that exists to be ordered from by our own
--    machinery and by nobody else. Today exactly one: the canary. Every path that texts
--    an owner checks it and skips (the fan-out's SMS leg, the stale-order escalation,
--    the printer heartbeat), and the storefront answers it with the ordinary 404.
--    A flag, **not** a nullable phone: `phone_e164` stays NOT NULL, because a real
--    restaurant created without one would silently never be texted about an order.
--    `DEFAULT false NOT NULL` is correct by construction for every existing row — each
--    of them is a real (or test) restaurant — and on Postgres 11+ a constant default is
--    a catalog-only change, so it does not rewrite `locations`.
--
-- 2. `canary_runs` — one row per canary run: when, the verdict, the order it placed,
--    the ticket it saw, why it failed, and `alerted_at` for its "one text an hour".
--
-- 3. `payment_failovers` — one row per card order converted to pay-at-pickup because
--    Stripe could not be reached, written in the conversion's own transaction, with
--    `alerted_at` for the Stripe-outage alarm's "one text an hour".
--
-- **Both new tables are platform-global and exempt from RLS**, and each is argued at
-- its table in `src/db/schema/platform.ts` and named in the catalog assertion in
-- `src/repo/rls.test.ts`:
--
--   canary_runs         the run row is written *before* the canary location is looked
--                       up, so "there is no canary location" is itself a recorded
--                       failure that pages us. Scoped to that location, the row could
--                       not exist in exactly the case where the canary is most broken.
--   payment_failovers   Stripe is one dependency for every restaurant, so its alarm is
--                       one text an hour for the platform, and its cooldown has to see
--                       every restaurant's conversions at once. Ids only.
--
-- Their state is deliberately separate: a canary text must never buy a Stripe outage an
-- hour of silence, or the other way round.
--
-- Grants: 0008 revoked `app_user`'s default privileges on future tables, so each new
-- table is unreadable until granted here. SELECT, INSERT, UPDATE — **no DELETE**:
-- nothing prunes either table yet (retention of the canary's rows is a scheduled
-- follow-up). `locations.synthetic` needs no grant; `app_user`'s privileges on
-- `locations` are table-level (0008) and cover a new column. The enum type needs none
-- either: USAGE on a type in `public` is PUBLIC's by default.
--
-- Idempotent throughout (`IF NOT EXISTS`, and `duplicate_object` swallowed for the type
-- and the constraints, which have no such clause): Neon branches get reset.
DO $$ BEGIN
  CREATE TYPE "public"."canary_outcome" AS ENUM('running', 'confirmed', 'failed');
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "canary_runs" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"inngest_run_id" text NOT NULL,
	"started_at" timestamp with time zone DEFAULT now() NOT NULL,
	"finished_at" timestamp with time zone,
	"outcome" "canary_outcome" DEFAULT 'running' NOT NULL,
	"location_id" uuid,
	"order_id" uuid,
	"print_job_id" uuid,
	"failure_reason" text,
	"alerted_at" timestamp with time zone,
	CONSTRAINT "canary_runs_inngest_run_id_unique" UNIQUE("inngest_run_id")
);
--> statement-breakpoint
CREATE TABLE IF NOT EXISTS "payment_failovers" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"order_id" uuid NOT NULL,
	"location_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"alerted_at" timestamp with time zone,
	CONSTRAINT "payment_failovers_order_id_unique" UNIQUE("order_id")
);
--> statement-breakpoint
ALTER TABLE "locations" ADD COLUMN IF NOT EXISTS "synthetic" boolean DEFAULT false NOT NULL;--> statement-breakpoint
-- `canary_runs.print_job_id` has no foreign key on purpose: the run records the ticket it
-- saw and then deletes it (a synthetic location has no printer to collect it).
DO $$ BEGIN
  ALTER TABLE "canary_runs" ADD CONSTRAINT "canary_runs_location_id_locations_id_fk" FOREIGN KEY ("location_id") REFERENCES "public"."locations"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "canary_runs" ADD CONSTRAINT "canary_runs_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "payment_failovers" ADD CONSTRAINT "payment_failovers_order_id_orders_id_fk" FOREIGN KEY ("order_id") REFERENCES "public"."orders"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
DO $$ BEGIN
  ALTER TABLE "payment_failovers" ADD CONSTRAINT "payment_failovers_location_id_locations_id_fk" FOREIGN KEY ("location_id") REFERENCES "public"."locations"("id") ON DELETE no action ON UPDATE no action;
EXCEPTION WHEN duplicate_object THEN NULL;
END $$;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "canary_runs_started_idx" ON "canary_runs" USING btree ("started_at");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "canary_runs_alerted_idx" ON "canary_runs" USING btree ("alerted_at") WHERE "canary_runs"."alerted_at" is not null;--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "payment_failovers_created_idx" ON "payment_failovers" USING btree ("created_at");--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "payment_failovers_alerted_idx" ON "payment_failovers" USING btree ("alerted_at") WHERE "payment_failovers"."alerted_at" is not null;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON TABLE "canary_runs" TO app_user;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON TABLE "payment_failovers" TO app_user;
